// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Cooler, ERC20, IDelegate, CoolerFactory} from "../src/Cooler.sol";

contract InvMutTest is Test {
    Cooler c;
    CoolerFactory factory;
    MockToken collat;
    MockToken debtTok;
    address actor = address(0xA11CE);

    function setUp() public {
        factory = new CoolerFactory();
        collat = new MockToken("COL", "COL");
        debtTok = new MockToken("DEBT", "DEBT");
    }

    function testFuzz_property(
        uint256 amount,
        uint256 interest,
        uint256 ltc,
        uint256 duration,
        address to
    ) public {
        amount = bound(amount, 1e18, 1e24);
        interest = bound(interest, 0, 1e18);
        ltc = bound(ltc, 1e18, 1e24);
        duration = bound(duration, 1, 365 days);
        vm.assume(to != address(0));
        vm.assume(to != actor);

        // actor creates the cooler pair and requests a loan
        address coolerAddr = factory.generateCooler(collat, debtTok);
        c = Cooler(coolerAddr);

        uint256 collateralNeeded = c.collateralFor(amount, ltc);
        collat.mint(actor, collateralNeeded);

        vm.startPrank(actor);
        collat.approve(coolerAddr, collateralNeeded);
        c.requestLoan(amount, interest, ltc, duration);
        vm.stopPrank();

        // the test contract is the lender: it clears the request, becoming loans[0].lender
        debtTok.mint(address(this), amount);
        debtTok.approve(coolerAddr, amount);
        c.clearRequest(0, false, false);

        // lender approves a transfer of loan 0 to `to`
        c.approveTransfer(to, 0);

        // rule: any completed approveTransfer by the loan's recorded lender sets approvals(loanID) == to
        assertTrue(c.approvals(0) == to);
    }
}

contract MockToken is ERC20, IDelegate {
    constructor(string memory n, string memory s) ERC20(n, s, 18) {}

    function mint(address to_, uint256 amount_) external {
        _mint(to_, amount_);
    }

    function approve(address spender_, uint256 amount_) public override returns (bool) {
        return super.approve(spender_, amount_);
    }

    function transfer(address to_, uint256 amount_) public override returns (bool) {
        return super.transfer(to_, amount_);
    }

    function transferFrom(address from_, address to_, uint256 amount_) public override returns (bool) {
        return super.transferFrom(from_, to_, amount_);
    }

    function delegate(address) external pure override {}
}
